<?php require_once 'config/db.php';require_once 'includes/auth.php';require_role(['admin','report_staff']);$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$customer=(int)($_GET['customer_id']??0);$daily=$conn->prepare("SELECT DATE(order_date) day,COUNT(*) orders,COALESCE(SUM(total),0) revenue FROM orders WHERE DATE(order_date) BETWEEN ? AND ? AND status NOT IN ('Cancelled','Rejected') GROUP BY DATE(order_date) ORDER BY day DESC");$daily->bind_param('ss',$from,$to);$daily->execute();$dailyRows=$daily->get_result();$cs=$conn->query("SELECT id,name,email FROM users WHERE role='customer' ORDER BY name");$sql="SELECT u.id,u.name,u.email,COUNT(o.id) orders,COALESCE(SUM(CASE WHEN o.status NOT IN ('Cancelled','Rejected') THEN o.total ELSE 0 END),0) total FROM users u LEFT JOIN orders o ON o.customer_id=u.id AND DATE(o.order_date) BETWEEN ? AND ? WHERE u.role='customer'";if($customer)$sql.=' AND u.id=?';$sql.=' GROUP BY u.id ORDER BY total DESC';$s=$conn->prepare($sql);if($customer)$s->bind_param('ssi',$from,$to,$customer);else $s->bind_param('ss',$from,$to);$s->execute();$customerRows=$s->get_result();include 'includes/header.php';?><div class="card"><h2>Reports</h2><form method="get" class="grid"><div><label>From date</label><input type="date" name="from" value="<?=h($from)?>" required></div><div><label>To date</label><input type="date" name="to" value="<?=h($to)?>" required></div><div><label>Customer report</label><select name="customer_id"><option value="0">All customers</option><?php while($c=$cs->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$customer===$c['id']?'selected':''?>><?=h($c['name'])?> — <?=h($c['email'])?></option><?php endwhile;?></select></div><div><button class="btn">Generate Report</button></div></form></div><div class="card"><h3>Individual / Total Customer Report</h3><table><tr><th>Customer</th><th>Email</th><th>Orders</th><th>Order Value</th></tr><?php while($x=$customerRows->fetch_assoc()):?><tr><td><?=h($x['name'])?></td><td><?=h($x['email'])?></td><td><?=$x['orders']?></td><td>₹<?=number_format($x['total'],2)?></td></tr><?php endwhile;?></table></div><div class="card"><h3>Daily / Calendar-wise Summary</h3><table><tr><th>Date</th><th>Orders</th><th>Revenue</th></tr><?php while($x=$dailyRows->fetch_assoc()):?><tr><td><?=h($x['day'])?></td><td><?=$x['orders']?></td><td>₹<?=number_format($x['revenue'],2)?></td></tr><?php endwhile;?></table></div><?php include 'includes/footer.php';?>